$values->unique('id') as $value)<option value="{{ $value->id }}">{{ $value->value }}</option>@endforeach</select></label>@endforeach<input type="hidden" name="variant_id" id="variant_id"><input type="number" name="quantity" value="1" min="1" class="w-24 rounded-xl border px-4 py-3"><p id="variant-stock" class="text-sm text-slate-500"></p><button class="rounded-xl bg-slate-950 px-7 py-3 font-bold text-white">Add variant to cart</button></form><script>const variants=@json($activeVariants->map(fn($v)=>['id'=>$v->id,'stock'=>$v->stock,'price'=>$v->price,'values'=>$v->attributeValues->pluck('id')->values()]));const selectors=[...document.querySelectorAll('.variant-selector')];const sync=()=>{const ids=selectors.map(s=>+s.value);const v=variants.find(x=>ids.every(id=>x.values.includes(id)));document.getElementById('variant_id').value=v?.id||'';document.getElementById('variant-stock').textContent=v?(v.stock?'Stock: '+v.stock:'Out of stock'):'Combination unavailable';};selectors.forEach(s=>s.addEventListener('change',sync));sync();</script>@else<p class="mt-6 text-sm text-slate-500">Stock: {{ $product->stock }}</p>@if($product->stock>0)<form method="POST" action="{{ route('cart.add',$product) }}" class="mt-8 flex items-center gap-3">@csrf<input type="number" name="quantity" value="1" min="1" max="{{ $product->stock }}" class="w-24 rounded-xl border px-4 py-3"><button class="rounded-xl bg-slate-950 px-7 py-3 font-bold text-white">Add to cart</button></form>@else<div class="mt-8 rounded-xl bg-red-50 px-5 py-3 font-bold text-red-600">Out of stock</div>@endif@endif</div></section>
